{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows strong bearish signals.",
    "Reduce forecast magnitude by 5-10% after a spike in price (e.g., >75% above recent mean) to avoid overshoot.",
    "Apply mean reversion bias: if forecast is >10% above recent 7-day average, reduce by 1-2% per day until convergence.",
    "Increase downward bias when sentiment is positive but price is trending downward (e.g., sentiment >0 but true price declines).",
    "Avoid overreacting to short-term sentiment swings — lag correction: if sentiment changes sharply, delay forecast adjustment by 1-2 days.",
    "For long-term horizons (>7 days), apply smoothing: reduce forecast volatility by 15-20% to avoid overfitting to recent noise."
  ]
}
